(window.WCD=window.WCD||[]).push(["injures",[["Finj_connard",1,"francaise","Connard","R","« Connard » est l'une des insultes les plus courantes en français, pour un homme jugé stupide ou méprisable. Sa version féminine est « connasse ».",111,"https://fr.wiktionary.org/wiki/Connard","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-connard.webp"],["Finj_connasse",2,"francaise","Connasse","PC","« Connasse » est la version féminine de « connard ». Elle a même eu sa série et son film avec Camille Cottin (Connasse, princesse des cœurs).",108,"https://fr.wiktionary.org/wiki/Connasse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-connasse.webp"],["Finj_salope",3,"francaise","Salope","R","« Salope » est une insulte vulgaire très répandue, au départ pour une femme jugée sale ou de mauvaise vie, aujourd'hui pour toute personne qui joue un sale tour.",106,"https://fr.wiktionary.org/wiki/Salope","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-salope.webp"],["Finj_salaud",4,"francaise","Salaud","PC","« Salaud » désigne un homme malhonnête, sans scrupules. Sartre en avait même fait un concept philosophique pour ceux qui fuient leur liberté.",116,"https://fr.wiktionary.org/wiki/Salaud","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-salaud.webp"],["Finj_enfoire",5,"francaise","Enfoiré","R","« Enfoiré » est une insulte pour un sale type… mais aussi le nom des Enfoirés, la troupe d'artistes des Restos du cœur lancée par Coluche.",113,"https://fr.wiktionary.org/wiki/Enfoiré","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-enfoire.webp"],["Finj_abruti",6,"francaise","Abruti","C","« Abruti » désigne quelqu'un de stupide, comme rendu bête par l'abrutissement. Un classique des disputes de voisinage.",null,"https://fr.wiktionary.org/wiki/Abruti","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-abruti.webp"],["Finj_cretin",7,"francaise","Crétin","C","« Crétin » vient d'un mot des Alpes qui désignait au départ des malades. Il est devenu une insulte banale pour un imbécile.",113,"https://fr.wiktionary.org/wiki/Crétin","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-cretin.webp"],["Finj_imbecile",8,"francaise","Imbécile","C","« Imbécile » vient du latin imbecillus, « faible ». Il désigne une personne qui manque d'intelligence ou de bon sens.",null,"https://fr.wiktionary.org/wiki/Imbécile","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-imbecile.webp"],["Finj_andouille",9,"francaise","Andouille","C","« Andouille » désigne gentiment un nigaud, quelqu'un d'un peu bête. Bien plus tendre que la charcuterie du même nom.",null,"https://fr.wiktionary.org/wiki/Andouille","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-andouille.webp"],["Finj_couillon",10,"francaise","Couillon","C","« Couillon » désigne un idiot ou un naïf, très utilisé dans le sud de la France où il peut presque être affectueux.",null,"https://fr.wiktionary.org/wiki/Couillon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-couillon.webp"],["Finj_ducon",11,"francaise","Ducon","PC","« Ducon » est une contraction moqueuse de « du con », pour traiter quelqu'un d'imbécile. On dit aussi « Ducon-la-joie ».",null,"https://fr.wiktionary.org/wiki/Ducon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-ducon.webp"],["Finj_trou_du_cul",12,"francaise","Trou du cul","PC","« Trou du cul » est une insulte imagée et vulgaire pour une personne qu'on méprise profondément.",null,"https://fr.wiktionary.org/wiki/Trou_du_cul","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-trou-du-cul.webp"],["Finj_petasse",13,"francaise","Pétasse","C","« Pétasse » désigne une femme jugée vulgaire ou prétentieuse. Une insulte très présente dans les cours de récré des années 2000.",115,"https://fr.wiktionary.org/wiki/Pétasse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-petasse.webp"],["Finj_pouffiasse",14,"francaise","Pouffiasse","C","« Pouffiasse » est une insulte vulgaire pour une femme jugée vulgaire et ridicule.",null,"https://fr.wiktionary.org/wiki/Pouffiasse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pouffiasse.webp"],["Finj_bouffon",15,"francaise","Bouffon","C","« Bouffon » désignait le fou du roi ; c'est devenu une insulte pour quelqu'un de ridicule, qu'on ne prend pas au sérieux.",112,"https://fr.wiktionary.org/wiki/Bouffon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-bouffon.webp"],["Finj_bolosse",16,"francaise","Bolosse","PC","« Bolosse » (ou boloss) est un mot d'argot des années 2000 pour un naïf, un faible, un nul qu'on peut facilement arnaquer.",112,"https://fr.wiktionary.org/wiki/Bolosse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-bolosse.webp"],["Finj_cassos",17,"francaise","Cassos","C","« Cassos » est l'abréviation de « cas social », pour une personne jugée misérable et sans manières.",null,"https://fr.wiktionary.org/wiki/Cassos","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-cassos.webp"],["Finj_beauf",18,"francaise","Beauf","PC","« Beauf » vient du personnage du dessinateur Cabu : le Français moyen, vulgaire, sûr de lui et fan de pastis.",null,"https://fr.wiktionary.org/wiki/Beauf","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-beauf.webp"],["Finj_blaireau",19,"francaise","Blaireau","C","« Blaireau » désigne un type ringard et un peu bête. Le pauvre animal n'a rien demandé.",null,"https://fr.wiktionary.org/wiki/Blaireau","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-blaireau.webp"],["Finj_tocard",20,"francaise","Tocard","C","« Tocard » désigne un nul, un incapable. À l'origine, c'était un cheval de course sans chance de gagner.",null,"https://fr.wiktionary.org/wiki/Tocard","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-tocard.webp"],["Finj_naze",21,"francaise","Naze","C","« Naze » (ou nase) désigne quelqu'un de nul, ou de complètement épuisé : « Je suis naze ce soir ».",null,"https://fr.wiktionary.org/wiki/Naze","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-naze.webp"],["Finj_tete_de_nud",22,"francaise","Tête de nœud","C","« Tête de nœud » est une insulte imagée et un peu grivoise pour traiter quelqu'un d'imbécile.",null,"https://fr.wiktionary.org/wiki/Tête_de_nœud","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-tete-de-nud.webp"],["Finj_tete_a_claques",23,"francaise","Tête à claques","C","Une « tête à claques » est une personne si agaçante qu'on aurait envie de lui donner des gifles.",null,"https://fr.wiktionary.org/wiki/Tête_à_claques","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-tete-a-claques.webp"],["Finj_branleur",24,"francaise","Branleur","C","« Branleur » désigne un fainéant qui ne fait rien de ses journées. Synonyme : glandeur.",null,"https://fr.wiktionary.org/wiki/Branleur","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-branleur.webp"],["Finj_leche_cul",25,"francaise","Lèche-cul","C","Un « lèche-cul » est quelqu'un qui flatte bassement ses supérieurs pour obtenir des faveurs. Version polie : lèche-bottes.",108,"https://fr.wiktionary.org/wiki/Lèche-cul","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-leche-cul.webp"],["Finj_fayot",26,"francaise","Fayot","C","Le « fayot » est l'élève qui fait du zèle pour plaire au professeur. À l'origine, c'est un mot d'argot pour le haricot sec.",110,"https://fr.wiktionary.org/wiki/Fayot","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-fayot.webp"],["Finj_mytho",27,"francaise","Mytho","C","« Mytho » (pour mythomane) désigne quelqu'un qui ment ou invente des histoires : « Arrête, t'es trop mytho ! »",null,"https://fr.wiktionary.org/wiki/Mytho","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-mytho.webp"],["Finj_boulet",28,"francaise","Boulet","C","Un « boulet » est une personne encombrante ou maladroite qui ralentit les autres, comme le boulet attaché au pied des bagnards.",113,"https://fr.wiktionary.org/wiki/Boulet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-boulet.webp"],["Finj_guignol",29,"francaise","Guignol","C","« Guignol » vient de la célèbre marionnette lyonnaise ; c'est devenu une insulte pour quelqu'un de ridicule et peu sérieux.",114,"https://fr.wiktionary.org/wiki/Guignol","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-guignol.webp"],["Finj_rageux",30,"francaise","Rageux","PC","« Rageux » désigne sur internet une personne jalouse qui critique tout par frustration. « Les rageux vont rager ! »",null,"https://fr.wiktionary.org/wiki/Rageux","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-rageux.webp"],["Finj_gourgandine",31,"ringarde","Gourgandine","L","« Gourgandine » est une vieille insulte du XVIIe siècle pour une femme de petite vertu. Aujourd'hui, on l'utilise surtout pour rire tant elle sonne désuète.",113,"https://fr.wiktionary.org/wiki/Gourgandine","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-gourgandine.webp"],["Finj_malotru",32,"ringarde","Malotru","R","« Malotru » désigne un homme mal élevé et grossier. Le mot vient du latin male astrucus, « né sous une mauvaise étoile ».",111,"https://fr.wiktionary.org/wiki/Malotru","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-malotru.webp"],["Finj_goujat",33,"ringarde","Goujat","PC","Un « goujat » est un homme grossier et sans délicatesse, surtout envers les femmes. À l'origine, c'était un valet d'armée.",113,"https://fr.wiktionary.org/wiki/Goujat","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-goujat.webp"],["Finj_faquin",34,"ringarde","Faquin","R","« Faquin » est une insulte du théâtre classique (Molière l'adore) pour un homme de rien, impertinent et méprisable.",null,"https://fr.wiktionary.org/wiki/Faquin","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-faquin.webp"],["Finj_maraud",35,"ringarde","Maraud","PC","« Maraud » est une vieille insulte pour un vaurien, une canaille. Cyrano de Bergerac en fait grand usage.",null,"https://fr.wiktionary.org/wiki/Maraud","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-maraud.webp"],["Finj_paltoquet",36,"ringarde","Paltoquet","R","« Paltoquet » désigne un homme insignifiant mais prétentieux. Le capitaine Haddock l'a remis au goût du jour.",null,"https://fr.wiktionary.org/wiki/Paltoquet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-paltoquet.webp"],["Finj_foutriquet",37,"ringarde","Foutriquet","R","« Foutriquet » est une vieille moquerie pour un homme insignifiant. On l'a utilisée contre le président Adolphe Thiers, très petit de taille.",111,"https://fr.wiktionary.org/wiki/Foutriquet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-foutriquet.webp"],["Finj_freluquet",38,"ringarde","Freluquet","PC","Un « freluquet » est un jeune homme maigrelet et prétentieux, qui se donne des airs.",null,"https://fr.wiktionary.org/wiki/Freluquet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-freluquet.webp"],["Finj_pignouf",39,"ringarde","Pignouf","PC","« Pignouf » désigne une personne grossière et mal élevée. Un mot délicieusement rétro.",null,"https://fr.wiktionary.org/wiki/Pignouf","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pignouf.webp"],["Finj_olibrius",40,"ringarde","Olibrius","R","Un « olibrius » est un individu bizarre et un peu fanfaron, du nom d'un empereur romain réputé ridicule.",null,"https://fr.wiktionary.org/wiki/Olibrius","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-olibrius.webp"],["Finj_jean_foutre",41,"ringarde","Jean-foutre","PC","Un « jean-foutre » est un homme sur lequel on ne peut pas compter, un incapable qui se moque de tout.",null,"https://fr.wiktionary.org/wiki/Jean-foutre","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-jean-foutre.webp"],["Finj_peronnelle",42,"ringarde","Péronnelle","R","« Péronnelle » est une vieille insulte pour une jeune femme sotte et bavarde, qui parle à tort et à travers.",null,"https://fr.wiktionary.org/wiki/Péronnelle","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-peronnelle.webp"],["Finj_pimbeche",43,"ringarde","Pimbêche","PC","Une « pimbêche » est une femme hautaine et prétentieuse, qui fait des manières.",null,"https://fr.wiktionary.org/wiki/Pimbêche","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pimbeche.webp"],["Finj_mijauree",44,"ringarde","Mijaurée","PC","Une « mijaurée » est une femme aux manières affectées et ridicules, qui fait la difficile.",null,"https://fr.wiktionary.org/wiki/Mijaurée","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-mijauree.webp"],["Finj_becasse",45,"ringarde","Bécasse","C","« Bécasse » traite une femme de sotte, comme l'oiseau réputé idiot. Le masculin serait « bécasseau ».",null,"https://fr.wiktionary.org/wiki/Bécasse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-becasse.webp"],["Finj_butor",46,"ringarde","Butor","PC","Un « butor » est un homme grossier, lourdaud et sans finesse. C'est aussi le nom d'un oiseau des marais.",null,"https://fr.wiktionary.org/wiki/Butor","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-butor.webp"],["Finj_moule_a_gaufres",47,"ringarde","Moule à gaufres","R","« Moule à gaufres » est l'une des insultes cultes du capitaine Haddock dans Tintin, parfaite pour traiter quelqu'un d'idiot sans être vulgaire.",115,"https://fr.wiktionary.org/wiki/Moule_à_gaufres","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-moule-a-gaufres.webp"],["Finj_bachi_bouzouk",48,"ringarde","Bachi-bouzouk","R","« Bachi-bouzouk » vient des soldats irréguliers de l'Empire ottoman ; le capitaine Haddock en a fait une de ses insultes favorites.",111,"https://fr.wiktionary.org/wiki/Bachi-bouzouk","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-bachi-bouzouk.webp"],["Finj_ectoplasme",49,"ringarde","Ectoplasme","PC","« Ectoplasme » désigne une personne molle et sans consistance. Encore une trouvaille du capitaine Haddock.",null,"https://fr.wiktionary.org/wiki/Ectoplasme","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-ectoplasme.webp"],["Finj_cornichon",50,"ringarde","Cornichon","C","« Cornichon » est une insulte gentillette pour un niais, un benêt. Parfait pour les enfants.",null,"https://fr.wiktionary.org/wiki/Cornichon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-cornichon.webp"],["Finj_vieille_baderne",51,"ringarde","Vieille baderne","PC","Une « vieille baderne » est un vieil homme, souvent militaire, borné et rabâcheur.",null,"https://fr.wiktionary.org/wiki/Vieille_baderne","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-vieille-baderne.webp"],["Finj_klet",52,"belge","Klet","R","« Klet » est une insulte bruxelloise pour un idiot, un abruti. On l'entend aussi en Flandre.",null,"https://fr.wiktionary.org/wiki/Klet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-klet.webp"],["Finj_zievereer",53,"belge","Zievereer","R","Un « zievereer » est, en bruxellois, quelqu'un qui raconte des bêtises ou des histoires à dormir debout. Le verbe : zieverer.",115,"https://fr.wiktionary.org/wiki/Zievereer","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-zievereer.webp"],["Finj_babeleer",54,"belge","Babeleer","PC","Un « babeleer » est un bavard intarissable, quelqu'un qui parle sans arrêt. Le verbe : babeler.",null,"https://fr.wiktionary.org/wiki/Babeleer","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-babeleer.webp"],["Finj_stoefer",55,"belge","Stoefer","PC","Un « stoefer » (ou stoeffer) est un vantard, un frimeur qui se croit plus fort que tout le monde. Cousin du dikkenek.",null,"https://fr.wiktionary.org/wiki/Stoefer","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-stoefer.webp"],["Finj_snotneus",56,"belge","Snotneus","PC","« Snotneus » (« nez morveux ») est une insulte flamande et bruxelloise pour un gamin insolent, un petit morveux.",null,"https://fr.wiktionary.org/wiki/Snotneus","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-snotneus.webp"],["Finj_zot",57,"belge","Zot","C","« Zot » veut dire fou ou idiot en flamand et en bruxellois : « T'es zot ou quoi ? »",null,"https://fr.wiktionary.org/wiki/Zot","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-zot.webp"],["Finj_biesse",58,"belge","Bièsse","PC","« Bièsse » vient du wallon et signifie bête : « Ne fais pas ta bièsse ! ». Souvent affectueux.",null,"https://fr.wiktionary.org/wiki/Bièsse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-biesse.webp"],["Finj_smeerlap",59,"belge","Smeerlap","R","« Smeerlap » est une insulte flamande pour un salaud ou un sale type. Littéralement : un « chiffon gras ».",null,"https://fr.wiktionary.org/wiki/Smeerlap","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-smeerlap.webp"],["Finj_pottekijker",60,"belge","Pottekijker","PC","Un « pottekijker » est, en flamand, quelqu'un qui regarde dans les casseroles des autres : un curieux qui fourre son nez partout.",116,"https://fr.wiktionary.org/wiki/Pottekijker","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pottekijker.webp"],["Finj_il_lui_manque_une_frite_dans_le_cornet",61,"belge","Il lui manque une frite dans le cornet","L","« Il lui manque une frite dans le cornet » est la version belge de « il n'a pas toute sa tête ». Forcément, avec des frites.",116,"https://fr.wiktionary.org/wiki/Il_lui_manque_une_frite_dans_le_cornet","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-il-lui-manque-une-frite-dans-le-cornet.webp"],["Finj_niaiseux",62,"quebecoise","Niaiseux","R","« Niaiseux » est l'insulte québécoise de base pour quelqu'un de niais, de bête. On l'entend aussi comme verbe : « niaiser » quelqu'un, c'est se moquer de lui.",113,"https://fr.wiktionary.org/wiki/Niaiseux","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-niaiseux.webp"],["Finj_epais",63,"quebecoise","Épais","PC","Au Québec, traiter quelqu'un d'« épais » (ou « épaisse »), c'est le traiter d'imbécile. « Mautadit épais ! »",null,"https://fr.wiktionary.org/wiki/Épais","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-epais.webp"],["Finj_colon",64,"quebecoise","Colon","PC","Au Québec, un « colon » est un rustre ignorant et mal élevé, un péquenaud.",null,"https://fr.wiktionary.org/wiki/Colon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-colon.webp"],["Finj_teteux",65,"quebecoise","Téteux","PC","Un « téteux » est, au Québec, un lèche-bottes, ou quelqu'un qui insiste lourdement pour obtenir quelque chose.",null,"https://fr.wiktionary.org/wiki/Téteux","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-teteux.webp"],["Finj_gnochon",66,"quebecoise","Gnochon","PC","« Gnochon » est une insulte québécoise pour un imbécile, un nono.",null,"https://fr.wiktionary.org/wiki/Gnochon","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-gnochon.webp"],["Finj_cave",67,"quebecoise","Cave","C","Au Québec, être « cave », c'est être idiot ou naïf : « Fais pas ton cave ! »",null,"https://fr.wiktionary.org/wiki/Cave","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-cave.webp"],["Finj_sans_dessein",68,"quebecoise","Sans-dessein","R","Un « sans-dessein » est, au Québec, quelqu'un de niais et d'incapable, qui n'a « pas de dessein », pas de jugement.",null,"https://fr.wiktionary.org/wiki/Sans-dessein","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-sans-dessein.webp"],["Finj_baveux",69,"quebecoise","Baveux","C","Au Québec, être « baveux », c'est être arrogant et provocateur, chercher la bagarre.",null,"https://fr.wiktionary.org/wiki/Baveux","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-baveux.webp"],["Finj_toton",70,"quebecoise","Toton","C","« Toton » est une insulte québécoise pour un idiot, un imbécile. Assez gentille au fond.",null,"https://fr.wiktionary.org/wiki/Toton","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-toton.webp"],["Finj_mange_marde",71,"quebecoise","Mange-marde","PC","« Mange-marde » est une insulte québécoise bien grasse pour un minable ou un lèche-bottes.",null,"https://fr.wiktionary.org/wiki/Mange-marde","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-mange-marde.webp"],["Finj_tabarnak",72,"quebecoise","Tabarnak","E","« Tabarnak » est le plus célèbre des sacres québécois, tiré du « tabernacle » de l'église. Plus il est long (« Tabarnak de câlisse d'ostie ! »), plus on est fâché.",110,"https://fr.wiktionary.org/wiki/Tabarnak","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-tabarnak.webp"],["Finj_calisse",73,"quebecoise","Câlisse","R","« Câlisse » (du « calice ») est un sacre québécois. « Câlisse ton camp ! » veut dire « dégage ! ».",null,"https://fr.wiktionary.org/wiki/Câlisse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-calisse.webp"],["Finj_ostie",74,"quebecoise","Ostie","PC","« Ostie » (de « hostie ») est un sacre québécois qui sert à renforcer n'importe quoi : « un ostie de bon film ».",null,"https://fr.wiktionary.org/wiki/Ostie","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-ostie.webp"],["Finj_il_manque_des_bardeaux_sur_la_couverture",75,"quebecoise","Il manque des bardeaux sur la couverture","E","Au Québec, quand « il manque des bardeaux sur la couverture » (des tuiles sur le toit), c'est que la personne n'a pas toute sa tête.",113,"https://fr.wiktionary.org/wiki/Il_manque_des_bardeaux_sur_la_couverture","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-il-manque-des-bardeaux-sur-la-couverture.webp"],["Finj_t_es_pas_le_couteau_le_plus_aiguise_du_tiroir",76,"imagee","T'es pas le couteau le plus aiguisé du tiroir","M","« T'es pas le couteau le plus aiguisé du tiroir » est une façon imagée et polie de dire à quelqu'un qu'il n'est pas très intelligent.",115,"https://fr.wiktionary.org/wiki/T'es_pas_le_couteau_le_plus_aiguisé_du_tiroir","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-t-es-pas-le-couteau-le-plus-aiguise-du-tiroir.webp"],["Finj_il_n_a_pas_invente_l_eau_chaude",77,"imagee","Il n'a pas inventé l'eau chaude","E","« Il n'a pas inventé l'eau chaude » (ou « la poudre ») veut dire qu'une personne n'est pas une lumière.",null,"https://fr.wiktionary.org/wiki/Il_n'a_pas_inventé_l'eau_chaude","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-il-n-a-pas-invente-l-eau-chaude.webp"],["Finj_con_comme_un_balai",78,"imagee","Con comme un balai","R","Être « con comme un balai », c'est être extrêmement bête. Le balai n'a jamais pu se défendre.",null,"https://fr.wiktionary.org/wiki/Con_comme_un_balai","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-con-comme-un-balai.webp"],["Finj_bete_comme_ses_pieds",79,"imagee","Bête comme ses pieds","PC","« Bête comme ses pieds » : tellement bête qu'on se compare à la partie du corps la plus éloignée du cerveau.",null,"https://fr.wiktionary.org/wiki/Bête_comme_ses_pieds","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-bete-comme-ses-pieds.webp"],["Finj_avoir_une_case_en_moins",80,"imagee","Avoir une case en moins","PC","« Avoir une case en moins », c'est être un peu dérangé, comme s'il manquait une case dans le cerveau.",null,"https://fr.wiktionary.org/wiki/Avoir_une_case_en_moins","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-avoir-une-case-en-moins.webp"],["Finj_pas_la_lumiere_a_tous_les_etages",81,"imagee","Pas la lumière à tous les étages","E","« Il n'a pas la lumière à tous les étages » : sa tête est un immeuble où certains étages sont dans le noir.",null,"https://fr.wiktionary.org/wiki/Pas_la_lumière_à_tous_les_étages","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pas-la-lumiere-a-tous-les-etages.webp"],["Finj_lent_a_la_detente",82,"imagee","Lent à la détente","PC","Être « lent à la détente », c'est mettre du temps à comprendre une blague ou une situation.",null,"https://fr.wiktionary.org/wiki/Lent_à_la_détente","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-lent-a-la-detente.webp"],["Finj_le_qi_d_une_huitre",83,"imagee","Le QI d'une huître","R","Avoir « le QI d'une huître » : être aussi intelligent qu'un mollusque, ce qui n'est pas un compliment.",null,"https://fr.wiktionary.org/wiki/Le_QI_d'une_huître","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-le-qi-d-une-huitre.webp"],["Finj_pedaler_dans_la_choucroute",84,"imagee","Pédaler dans la choucroute","PC","« Pédaler dans la choucroute » (ou la semoule), c'est s'agiter dans tous les sens sans arriver à rien.",null,"https://fr.wiktionary.org/wiki/Pédaler_dans_la_choucroute","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pedaler-dans-la-choucroute.webp"],["Finj_faux_comme_un_jeton",85,"imagee","Faux comme un jeton","PC","Être « faux comme un jeton », c'est être hypocrite, comme une fausse pièce de monnaie.",null,"https://fr.wiktionary.org/wiki/Faux_comme_un_jeton","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-faux-comme-un-jeton.webp"],["Finj_va_te_faire_cuire_un_uf",86,"imagee","Va te faire cuire un œuf","R","« Va te faire cuire un œuf ! » est une façon polie et imagée d'envoyer quelqu'un promener.",null,"https://fr.wiktionary.org/wiki/Va_te_faire_cuire_un_œuf","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-va-te-faire-cuire-un-uf.webp"],["Finj_va_voir_ailleurs_si_j_y_suis",87,"imagee","Va voir ailleurs si j'y suis","PC","« Va voir ailleurs si j'y suis » : une manière ironique de demander à quelqu'un de partir.",null,"https://fr.wiktionary.org/wiki/Va_voir_ailleurs_si_j'y_suis","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-va-voir-ailleurs-si-j-y-suis.webp"],["Finj_tete_de_mule",88,"imagee","Tête de mule","C","Une « tête de mule » est une personne extrêmement têtue, aussi obstinée qu'une mule.",null,"https://fr.wiktionary.org/wiki/Tête_de_mule","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-tete-de-mule.webp"],["Finj_langue_de_vipere",89,"imagee","Langue de vipère","C","Une « langue de vipère » est une personne qui dit du mal des autres, avec une langue aussi venimeuse qu'un serpent.",null,"https://fr.wiktionary.org/wiki/Langue_de_vipère","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-langue-de-vipere.webp"],["Finj_avoir_des_oursins_dans_les_poches",90,"imagee","Avoir des oursins dans les poches","R","Avoir « des oursins dans les poches », c'est être radin : impossible de mettre la main à la poche sans se piquer.",null,"https://fr.wiktionary.org/wiki/Avoir_des_oursins_dans_les_poches","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-avoir-des-oursins-dans-les-poches.webp"],["Finj_moche_comme_un_pou",91,"imagee","Moche comme un pou","C","Être « moche comme un pou », c'est être très laid. Les poux ne sont pas connus pour leur beauté.",null,"https://fr.wiktionary.org/wiki/Moche_comme_un_pou","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-moche-comme-un-pou.webp"],["Finj_pas_le_crayon_le_plus_taille_de_la_trousse",92,"imagee","Pas le crayon le plus taillé de la trousse","R","« Pas le crayon le plus taillé de la trousse » : la version scolaire du couteau pas très aiguisé.",null,"https://fr.wiktionary.org/wiki/Pas_le_crayon_le_plus_taillé_de_la_trousse","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/i-pas-le-crayon-le-plus-taille-de-la-trousse.webp"]]]);